<?php declare(strict_types=1);
$groupMoney=static fn(int $cents):string=>($cents>0?'+':'').euro($cents);$bankGroupPortions=($bankGroupActive['original']['schema']??1)===2;
?>
<section class="card" data-bank-group-current="<?=e($bankGroupActive['group']['id'])?>">
<h2><?=e($bankEvidenceText($bankGroupPortions?'Banknachweis für Bankteilbeträge':'Banknachweis für zusammengehörige Teilbewegungen'))?></h2>
<p><?=e($bankEvidenceText($bankGroupPortions?'Dieser ursprüngliche Banknachweis belegt genau die folgenden Teilbeträge. Die vollständigen ursprünglichen Bewegungen und Belege bleiben erhalten.':($bankGroupActive['link']['operation']==='duplicate'?'Die doppelte Übernahme wurde durch genau eine Gegenbuchung ausgeglichen. Dieser Banknachweis gehört zu den folgenden ursprünglichen Teilbewegungen.':'Dieser Banknachweis verbindet die folgenden bereits erfassten Teilbewegungen. Geld, Belege und Zuordnungen bleiben erhalten.')))?></p>
<?php if($bankGroupPortions&&$bankGroupActive['link']['operation']==='duplicate'):?><p class="notice"><?=e($bankEvidenceText('Die doppelte Übernahme wurde durch genau eine Gegenbuchung ausgeglichen. Dieser Banknachweis gehört zu den folgenden ursprünglichen Teilbewegungen.'))?></p><?php endif ?>
<?php if(isset($bankGroupActive['original']['source']['fee'])):$recordedFee=$bankGroupActive['original']['source']['fee'];?><section class="bank-import-history" data-bank-fee-recorded><h3><?=e($bankEvidenceText('Belegter Gebührenabzug'))?></h3><p><?=e($bankEvidenceText('Dieser ursprüngliche Gebührenabzug wurde einmal erfasst und seinem geprüften Ausgabebeleg zugeordnet. Weitere Bankreferenzen verwenden denselben vorhandenen Abzug.'))?></p><p><strong><?=e(euro(-(int)$recordedFee['cents']))?></strong> · <?=e($recordedFee['entry']['description'])?></p><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'finance','tab'=>'receipts','entry'=>$recordedFee['entry']['id']]))?>" target="_blank" rel="noopener"><?=e($bankEvidenceText('Gebührenbeleg mit Original und Freigabe öffnen'))?></a></section><?php endif ?>
<?php foreach($bankGroupActive['items']as$item):$component=$bankGroupActive['original']['source']['transactions'][$item['transaction_id']]; ?>
<article class="bank-import-row" data-bank-group-component="<?=e($item['transaction_id'])?>" data-bank-group-signed="<?=(int)$item['cents']?>"><div><strong><?=e($groupMoney((int)$item['cents']))?></strong><p><?=e(dateDe($component['booked_on']).' · '.$component['counterparty'].' · '.$component['description'])?></p><?php if($bankGroupPortions):?><p><?=e($bankEvidenceText('Vollständige ursprüngliche Bewegung'))?>: <?=e($groupMoney((int)$component['cents']))?></p><?php try{$liveProof=$finance->transactionDetail($item['transaction_id']);?><p class="muted" data-bank-proof-current="<?=e($item['transaction_id'])?>"><?=e($bankEvidenceText('Derzeit durch Banknachweise belegt'))?>: <?=e(euro((int)$liveProof['bank_proved_cents']))?><br><?=e($bankEvidenceText('Noch ohne Banknachweis'))?>: <?=e(euro((int)$liveProof['bank_unproved_cents']))?></p><?php }catch(DomainException $failure){?><p class="notice" role="status"><?=e($bankEvidenceText($failure->getMessage()))?></p><?php }endif ?></div><a class="btn btn-outline theme-secondary" href="<?=e(url(bankTransactionContext($item['transaction_id'],$_GET)))?>"><?=e($bankEvidenceText('Teilbewegung mit Belegen öffnen'))?></a></article>
<?php endforeach ?>
<p><strong><?=e($bankEvidenceText('Bestätigter Banknettobetrag'))?>: <span data-bank-group-total="<?=(int)$bankGroupActive['group']['total_cents']?>"><?=e($groupMoney((int)$bankGroupActive['group']['total_cents']))?></span></strong></p>
<?php $bankReasonOriginal($bankGroupActive['link']['reason']);?><a class="btn btn-outline theme-secondary" data-bank-group-original download data-navigation-native href="<?=e(url(array_replace($importContext,['import_group_original'=>$bankGroupActive['link']['id']])))?>"><?=e($bankEvidenceText('Ursprünglichen Sammelbanknachweis herunterladen'))?></a><p class="muted">SHA-256: <?=e($bankGroupActive['link']['original_sha256'])?></p>
</section>
